INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b1b2c3d4-0005-4000-8000-000000000005', 'a1b2c3d4-0004-4000-8000-000000000004', 5, 'O Perdão Radical', 'Quebrando a maior corrente de todas', '{"intro": "Se h\u00e1 uma corrente que prende mais almas do que qualquer outra, \u00e9 a falta de perd\u00e3o. O ressentimento \u00e9 um veneno que bebemos esperando que o outro morra. E no entanto, quantos de n\u00f3s carregamos m\u00e1goas de anos \u2014 contra pais, amigos, ex-parceiros, contra n\u00f3s mesmos, e at\u00e9 contra Deus?\n\nJesus n\u00e3o sugeriu o perd\u00e3o \u2014 Ele o ordenou. E n\u00e3o uma vez, mas setenta vezes sete. Porque o perd\u00e3o n\u00e3o \u00e9 um sentimento: \u00e9 uma decis\u00e3o da vontade, sustentada pela gra\u00e7a. Hoje, vamos enfrentar a maior corrente.", "prayer": "Pai misericordioso, Tu que perdoaste a humanidade inteira do alto da Cruz, d\u00e1-me a gra\u00e7a de perdoar quem me feriu. Cura as feridas que carrego. Liberta-me do peso do ressentimento. Eu escolho perdoar \u2014 n\u00e3o porque seja f\u00e1cil, mas porque Tu me pedes. Am\u00e9m.", "practice": "Escreva uma carta de perd\u00e3o (que n\u00e3o precisa ser enviada). Dirija-se \u00e0 pessoa que te feriu. Descreva a dor, reconhe\u00e7a a ferida, e ent\u00e3o escreva as palavras: \"Eu escolho te perdoar. Entrego esta dor a Deus.\" Depois, reze um Pai-Nosso lentamente, detendo-se em \"perdoai as nossas ofensas assim como n\u00f3s perdoamos a quem nos tem ofendido.\"", "scripture": "\"Se perdoardes aos homens as suas ofensas, vosso Pai celeste tamb\u00e9m vos perdoar\u00e1.\" \u2014 Mt 6,14\n\n\"Pai, perdoa-lhes, porque n\u00e3o sabem o que fazem.\" \u2014 Lc 23,34", "reflection": "1. Quem voc\u00ea ainda n\u00e3o perdoou de verdade?\n2. Voc\u00ea se perdoou pelos seus pr\u00f3prios erros?\n3. H\u00e1 alguma m\u00e1goa contra Deus \u2014 por algo que Ele permitiu acontecer?", "journal_prompt": "Quem eu perdoei hoje? Como me senti ao escrever a carta de perd\u00e3o? O que mudou dentro de mim?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;